class FitnessTracker:
    STANDARD_BMI_RANGE_MALE = (20, 25)
    STANDARD_BMI_RANGE_FEMALE = (19, 24)

    ACTIVITY_FACTOR_SEDENTARY = 1.2
    ACTIVITY_FACTOR_MODERATE = 1.4
    ACTIVITY_FACTOR_ACTIVE = 1.6

    BMR_CONSTANT_MALE = 5
    BMR_CONSTANT_FEMALE = -161
    WEIGHT_COEFFICIENT = 10
    HEIGHT_COEFFICIENT = 6.25
    AGE_COEFFICIENT = 5

    def __init__(self, height, weight, age, sex) -> None:
        self._height = height
        self._weight = weight
        self._age = age
        self._sex = sex

    @property
    def height(self) -> float:
        return self._height

    @height.setter
    def height(self, value: float) -> None:
        self._height = value

    @property
    def weight(self) -> float:
        return self._weight

    @weight.setter
    def weight(self, value: float) -> None:
        self._weight = value

    @property
    def age(self) -> int:
        return self._age

    @age.setter
    def age(self, value: int) -> None:
        self._age = value

    @property
    def sex(self) -> str:
        return self._sex

    @sex.setter
    def sex(self, value: str) -> None:
        self._sex = value

    def get_BMI(self) -> float:
        return self.weight / (self.height ** 2)

    def get_standard_bmi_range(self) -> tuple:
        if self.sex == "male":
            return self.STANDARD_BMI_RANGE_MALE
        return self.STANDARD_BMI_RANGE_FEMALE

    def is_overweight(self) -> bool:
        bmi = self.get_BMI()
        _, upper_bound = self.get_standard_bmi_range()
        return bmi > upper_bound

    def is_underweight(self) -> bool:
        bmi = self.get_BMI()
        lower_bound, _ = self.get_standard_bmi_range()
        return bmi < lower_bound

    def condition_judge(self) -> int:
        if self.is_overweight():
            return 1
        elif self.is_underweight():
            return -1
        return 0

    def get_base_metabolic_rate(self) -> float:
        base_bmr = (
            self.WEIGHT_COEFFICIENT * self.weight
            + self.HEIGHT_COEFFICIENT * self.height
            + self.AGE_COEFFICIENT * self.age
        )
        if self.sex == "male":
            return base_bmr + self.BMR_CONSTANT_MALE
        return base_bmr + self.BMR_CONSTANT_FEMALE

    def get_activity_factor(self) -> float:
        condition = self.condition_judge()
        if condition == 1:
            return self.ACTIVITY_FACTOR_SEDENTARY
        elif condition == -1:
            return self.ACTIVITY_FACTOR_ACTIVE
        return self.ACTIVITY_FACTOR_MODERATE

    def calculate_calorie_intake(self) -> float:
        return self.get_base_metabolic_rate() * self.get_activity_factor()
